def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

count = 0
for n in range(2, 200):
    if is_prime(n):
        if n % 2 != 0 and n % 3 != 0:
            count += 1
            # print(n) # Optional: to see the list
print(count)
